def solve(mat):
    # determinant via Bareiss algorithm (fraction-free Gaussian elimination)
    n = len(mat)
    if n == 0:
        return 1
    if n == 1:
        return mat[0][0]
    # make a copy to avoid mutating input
    a = [row[:] for row in mat]
    sign = 1
    prev = 1
    for k in range(n-1):
        # pivot handling: if zero, swap with a lower row
        if a[k][k] == 0:
            swap_row = None
            for i in range(k+1, n):
                if a[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0
            a[k], a[swap_row] = a[swap_row], a[k]
            sign = -sign
        pivot = a[k][k]
        for i in range(k+1, n):
            for j in range(k+1, n):
                a[i][j] = (a[i][j]*pivot - a[i][k]*a[k][j]) // prev
            a[i][k] = 0
        prev = pivot
    return sign * a[n-1][n-1]

